with with_windows as (select *, avg(quantity) over (partition by order_id, product_id order by unit_price, id rows between 5 preceding and 1 preceding) as quantity_avg_5_prior, avg(quantity) over w_running as quantity_avg_2, stddev_samp(unit_price) over (partition by product_id) as product_id_stddev_samp_unit_price, sum(unit_price) over (partition by product_id, order_id order by unit_price, id rows between unbounded preceding and current row) as running_unit_price from order_items window w_running as (partition by product_id order by quantity, id rows between 2 preceding and current row)) select id, order_id, product_id, quantity, quantity_avg_2, running_unit_price from with_windows order by order_id desc, quantity_avg_2 desc
